  /** when I receive RESULTSSCREEN #3 */
  function s3(t: T): void {
    if (!eq(t.costumeName(), "nil")) {
      rt.stopOtherScripts(t, rt.activeThread);
      t.switchCostume("copy");
    }
  }

  /** when I receive CONTROLS #4 */
  const S4 = rt.unit("Hitbox/when I receive CONTROLS #4", (th, f) => {
    const t = th.target as T;
    for (;;) {
      switch (f.pc) {
      case 0:
        t.v.sh = "0";
        t.v.misc2 = "0";
        t.v.misc3 = "0";
      case 1:
        if (!gt(t.v.misc2, "0")) { f.pc = 2; continue; }
        t.v.misc3 = t.v.misc2;
        f.l[0] = rt.currentMSecs; f.l[1] = Math.max(0, 1000 * 2.5);
        rt.requestRedraw(); f.pc = 3; return Ctl.Yield;
      case 3:
        if (rt.currentMSecs - f.l[0]! < f.l[1]!) return Ctl.Yield;
        if (eq(t.v.misc2, t.v.misc3)) {
          t.v.misc2 = "0";
          t.v.misc3 = "0";
        }
      case 2:
        f.pc = 1; return Ctl.Yield;
        return Ctl.End;
      }
    }
  });

