  /** define calibrate %s */
  function p_calibrate(t: T, a_1_2: Value): void {
    if (contains(G.v.invincible, Math.abs(num((num(a_1_2) - 3))))) {
      t.hide();
    } else {
      t.show();
    }
    if (eq(a_1_2, "1")) {
      t.setXY(num(G.v._1x), num((num(G.v._1y) - 3)));
      t.setDirection(num(G.v._1dir));
    } else {
      t.setXY(num(G.v._2x), num((num(G.v._2y) - 3)));
      t.setDirection(num(G.v._2dir));
    }
  }

  /** define detectattack %s */
  function p_detectattack(t: T, a_1_2: Value): void {
    if ((eq(a_1_2, "1") && eq(G.v._1pmov, "0"))) {
      if ((eq(String(G.v.P1state).length, "2") || eq(G.v.P1state, ("D" + (String(Math.floor(num((num(G.v.gimmick1) / 180)))) + "M"))))) {
        if ((eq(G.v.char1, "12") && !eq(G.v.P1state, "DM"))) {
          t.switchCostume((String(G.v.gimmick1) + (String(G.v.P1state) + String(G.v.char1))));
        } else {
          p_canvascostume1(t);
        }
        t.setSize(100);
        t.setEffect("ghost", G.v.v);
        t.v.timer = num(t.v.timer) + 1;
        p_checkforgimmick(t, a_1_2);
        p_detecthurt(t, a_1_2);
        if (eq(mod(num(t.v.snd), 2), "0")) {
          if ((eq(G.v.char1, "3") && eq(G.v.P1state, "DM"))) {
            rt.startSound(t, ("Rae" + String(G.v.char2)));
          } else {
            rt.startSound(t, t.costumeName());
          }
          t.v.snd = num(t.v.snd) + 1;
        }
      } else {
        t.v.snd = "0";
        t.switchCostume("copy");
        t.v.timer = "0";
        t.hide();
      }
    } else {
      if ((eq(a_1_2, "2") && eq(G.v._2pmov, "0"))) {
        if ((eq(String(G.v.P2state).length, "2") || eq(G.v.P2state, ("D" + (String(Math.floor(num((num(G.v.gimmick2) / 180)))) + "M"))))) {
          if ((eq(G.v.char2, "12") && !eq(G.v.P2state, "DM"))) {
            t.switchCostume((String(G.v.gimmick2) + (String(G.v.P2state) + String(G.v.char2))));
          } else {
            p_canvascostume2(t);
          }
          t.setSize(100);
          t.setEffect("ghost", "100");
          t.v.timer = num(t.v.timer) + 1;
          p_checkforgimmick(t, a_1_2);
          p_detecthurt(t, a_1_2);
          if (eq(mod(num(t.v.snd), 2), "0")) {
            if ((eq(G.v.char2, "3") && eq(G.v.P2state, "DM"))) {
              rt.startSound(t, ("Rae" + String(G.v.char1)));
            } else {
              rt.startSound(t, t.costumeName());
            }
            t.v.snd = num(t.v.snd) + 1;
          }
        } else {
          t.v.snd = "0";
          t.switchCostume("copy");
          t.v.timer = "0";
          t.hide();
        }
      }
    }
  }

  /** define SCALARproj x %s y %s collide? %s pierce? %s reflect? %s Player %s physics? %s explosive? %s t' %s animate? %s animationSpeed %s Costume %s */
  function p_SCALARproj_x_y_collide_pierce_reflect_Player_physics_explosive_t_animate_animationSpeed_Costume(t: T, a_x: Value, a_y: Value, a_c: Value, a_p: Value, a_r: Value, a_1_2: Value, a_ph: Value, a_kaboom: Value, a_dt: Value, a_frames: Value, a_speed: Value, a_Cost: Value): void {
    if ((eq(G.v._1pmov, "0") || eq(G.v._2pmov, "0"))) {
      if (!eq(a_frames, "")) {
        t.switchCostume((String(a_Cost) + String((Math.floor(num(mod(num((rt.timer() * num(a_speed))), num(a_frames)))) + 1))));
      }
      t.setDirection(t.direction + num((num(t.v.initialdirection) * num(a_dt))));
      t.setXY(t.x, t.y + num(a_y));
      if (contains(a_ph, "y")) {
        p_physics(t, "y");
      }
      t.setXY(t.x + num((num(t.v.initialdirection) * num(a_x))), t.y);
      if (contains(a_ph, "x")) {
        p_physics(t, "x");
      }
      p_p_hit(t, a_c, a_p, a_r, a_1_2, a_kaboom);
    }
  }

