  /** define cafecheck %s */
  function p_cafecheck(t: T, a_1_2: Value): void {
    if (eq(a_1_2, "1")) {
      if (!(rt.keyPressed("right arrow") || (rt.keyPressed("left arrow") || (rt.keyPressed("up arrow") || rt.keyPressed("down arrow"))))) {
        t.v.c = "0";
      }
      if ((rt.keyPressed("right arrow") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c1!", "1");
      }
      if ((rt.keyPressed("left arrow") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c2!", "2");
      }
      if ((rt.keyPressed("up arrow") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c3!", "3");
      }
      if ((rt.keyPressed("down arrow") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c4!", "4");
      }
    } else {
      if (!(rt.keyPressed("d") || (rt.keyPressed("a") || (rt.keyPressed("w") || rt.keyPressed("s"))))) {
        t.v.c = "0";
      }
      if ((rt.keyPressed("d") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c1!", "1");
      }
      if ((rt.keyPressed("a") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c2!", "2");
      }
      if ((rt.keyPressed("w") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c3!", "3");
      }
      if ((rt.keyPressed("s") && eq(t.v.c, "0"))) {
        p_cafeblockinput(t, "c4!", "4");
      }
    }
  }

  /** define cafeblockinput %s %s */
  function p_cafeblockinput(t: T, a_snd: Value, a_id: Value): void {
    t.v.c = "1";
    if (eq(letterOf(t.v.misc1, t.v.misc2), a_id)) {
      t.setEffect("color", "60");
      p_cafescan(t, "80", a_snd, "!");
    } else {
      t.setEffect("color", "0");
      p_cafescan(t, "80", "", "!");
      if (!contains(t.v.misc1, ".")) {
        t.v.misc1 = num(t.v.misc1) + 0.5;
      }
    }
    t.setEffect("color", "0");
  }

