  /** define delaytoframe %s */
  function p_delaytoframe(t: T, a_t: Value): void {
    if (lt(t.v.timer, a_t)) {
      t.hide();
    }
  }

  /** define reTin %s */
  function p_reTin(t: T, a_1_2: Value): void {
    if (contains(t.costumeName(), "TinFish")) {
      if (eq(a_1_2, "1")) {
        G.v.gimmick1 = "1";
      } else {
        G.v.gimmick2 = "1";
      }
    }
  }

  /** define lingertoframe %s */
  function p_lingertoframe(t: T, a_t: Value): void {
    if (lt(a_t, t.v.timer)) {
      t.hide();
    }
  }

  /** define CostSwap %b */
  function p_CostSwap(t: T, a_ae: Value): void {
    if (bool(a_ae)) {
      t.switchCostume(item(G.l.hitboxswitch, (num(t.v.MiscHit2) + 3)));
      if (lt(t.v.snd, "2")) {
        t.v.snd = "2";
      }
    }
  }

  /** define Gimmickspt2 %b %s */
  function p_Gimmickspt2(t: T, a_boolean: Value, a_1_2: Value): void {
    if (bool(a_boolean)) {
      p_Move_x_y_Player_knockback(t, item(G.l.Gimmick_Moves, (num(t.v.MiscHit) + 3)), item(G.l.Gimmick_Moves, (num(t.v.MiscHit) + 4)), a_1_2, "");
    }
  }

